  1→//! Interactive terminal UI.
  2→
  3→use console::Term;
  4→use std::io::Write;
  5→use std::time::Duration;
  6→
  7→use crate::error::Result;
  8→
  9→use super::progress::format_duration;
 10→use super::{
 11→    prompt_user, should_use_colors, BivvyTheme, NonInteractiveUI, OutputMode, ProgressSpinner,
 12→    Prompt, PromptResult, RunSummary, SpinnerHandle, UserInterface,
 13→};
 14→
 15→/// Interactive terminal UI implementation.
 16→pub struct TerminalUI {
 17→    term: Term,
 18→    theme: BivvyTheme,
 19→    mode: OutputMode,
 20→}
 21→
 22→impl TerminalUI {
 23→    /// Create a new terminal UI.
 24→    pub fn new(mode: OutputMode) -> Self {
 25→        let theme = if should_use_colors() {
 26→            BivvyTheme::new()
 27→        } else {
 28→            BivvyTheme::plain()
 29→        };
 30→
 31→        Self {
 32→            term: Term::stdout(),
 33→            theme,
 34→            mode,
 35→        }
 36→    }
 37→}
 38→
 39→impl UserInterface for TerminalUI {
 40→    fn output_mode(&self) -> OutputMode {
 41→        self.mode
 42→    }
 43→
 44→    fn message(&mut self, msg: &str) {
 45→        if self.mode.shows_status() {
 46→            writeln!(self.term, "{}", msg).ok();
 47→        }
 48→    }
 49→
 50→    fn success(&mut self, msg: &str) {
 51→        if self.mode.shows_status() {
 52→            writeln!(self.term, "{}", self.theme.format_success(msg)).ok();
 53→        }
 54→    }
 55→
 56→    fn warning(&mut self, msg: &str) {
 57→        if self.mode.shows_status() {
 58→            writeln!(self.term, "{}", self.theme.format_warning(msg)).ok();
 59→        }
 60→    }
 61→
 62→    fn error(&mut self, msg: &str) {
 63→        writeln!(self.term, "{}", self.theme.format_error(msg)).ok();
 64→    }
 65→
 66→    fn prompt(&mut self, prompt: &Prompt) -> Result<PromptResult> {
 67→        prompt_user(prompt, &self.term)
 68→    }
 69→
 70→    fn start_spinner(&mut self, message: &str) -> Box<dyn SpinnerHandle> {
 71→        if self.mode.shows_spinners() {
