**`GitHubActionsSpinnerHandle`**:

```rust
/// Spinner handle for GitHub Actions that uses ::group::/::endgroup::.
struct GitHubActionsSpinnerHandle {
    finished: bool,
}

impl SpinnerHandle for GitHubActionsSpinnerHandle {
    fn set_message(&mut self, _msg: &str) {
        // No-op -- GitHub Actions groups don't support message updates
    }

    fn finish_success(&mut self, msg: &str) {
        if !self.finished {
            println!("::notice::{}", msg);
            println!("::endgroup::");
            self.finished = true;
        }
    }

    fn finish_error(&mut self, msg: &str) {
        if !self.finished {
            eprintln!("::error::{}", msg);
            println!("::endgroup::");
            self.finished = true;
        }
    }

    fn finish_skipped(&mut self, msg: &str) {
        if !self.finished {
            println!("::notice::{}", msg);
            println!("::endgroup::");
            self.finished = true;
        }
    }
}

impl Drop for GitHubActionsSpinnerHandle {
    fn drop(&mut self) {
        // Safety net: ensure endgroup is always emitted
        if !self.finished {
            println!("::endgroup::");
        }
    }
}
```

The `Drop` implementation is important: if a spinner handle is dropped without being finished (e.g., due to an early return or panic), the `::endgroup::` is still emitted, preventing broken log folding in GitHub Actions.

